// Room "P0 kitchen" (interior designer's part): the box x10..12, y2..4, z19..20 (plan.md P0 kitchen).
// Entered from the dining room through the door at (11,18), from the hall at x9 z20, and by the back door (10..11, 21).
// The focal piece is the stove wall on the north row, flanking the dining door: smoker west, furnace east, the
// door's inside cell (11,19) left clear. The work table (crafting table, a flower pot on it) sits in the south-east
// cell. The lane runs (10,20) -> (11,20) -> the back door, and (11,19) -> (11,20). A hanging lantern lights the lane.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  // y2: the stove wall (smoker, furnace, lit) and the work table; '.' is left as it is (clear lane)
  layers(g, [10, 2, 19], {
    "S": ["smoker", { facing: "south", lit: "true" }],
    "F": ["furnace", { facing: "south", lit: "true" }],
    "T": "crafting_table",
  }, [
    ["S.F", "..T"],
  ]);
  // y3: a flower pot on the work table (a pot needs a full top face: the table is one)
  layers(g, [10, 3, 19], {
    "P": "potted_poppy",
  }, [
    ["...", "..P"],
  ]);
  // y4: one lantern hanging from the ceiling block above, over the lane's second cell (not over a doorway)
  layers(g, [10, 4, 19], {
    "L": ["lantern", { hanging: "true" }],
  }, [
    ["...", ".L."],
  ]);
}

